class Solution {
public:
    int missingElement(vector<int>& nums, int k) {
        auto missing = [&](int i) -> int {
            return (nums[i] - nums[0]) - i;
        };

        int n = nums.size();
        if (k > missing(n - 1)) {
            return nums[n - 1] + (k - missing(n - 1));
        }

        int low = 0, high = n - 1;
        while (low < high) {
            int mid = low + (high - low + 1) / 2;
            if (missing(mid) < k) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return nums[low] + (k - missing(low));
    }
};

class Solution {
    public int missingElement(int[] nums, int k) {
        int n = nums.length;
        if (k > missing(nums, n - 1)) {
            return nums[n - 1] + (k - missing(nums, n - 1));
        }

        int low = 0, high = n - 1;
        while (low < high) {
            int mid = low + (high - low + 1) / 2;
            if (missing(nums, mid) < k) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }
        return nums[low] + (k - missing(nums, low));
    }

    private int missing(int[] nums, int i) {
        return (nums[i] - nums[0]) - i;
    }
}

var missingElement = function(nums, k) {
    const missing = (i) => (nums[i] - nums[0]) - i;

    const n = nums.length;
    if (k > missing(n - 1)) {
        return nums[n - 1] + (k - missing(n - 1));
    }

    let low = 0, high = n - 1;
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        if (missing(mid) < k) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    return nums[low] + (k - missing(low));
};
